const problems = [];
const notes = [];
const now = Date.now();
const B = 'https://144.31.194.174.nip.io/webhook/';
const API = 'https://144.31.194.174.nip.io/api/v1/';
// n8n API key (label n8n_year). Уже лежит в user_api_keys; вынесено сюда для проверки active.
// TODO: перевести в n8n-credential при ротации ключей (ревью Opus 5 — приватность).
const N8N_KEY = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJzdWIiOiJiNGE3MWNhZi03ZjVkLTQ1YjEtODE4MC03MTU4YTZkODA2OTciLCJpc3MiOiJuOG4iLCJhdWQiOiJwdWJsaWMtYXBpIiwianRpIjoiZGYwOTYwODUtNzM5Zi00NWI1LWFmNWQtZGI5YjIxMzgwM2U0IiwiaWF0IjoxNzg3NjE5Mzg0LCJleHAiOjE4MTkxMTYwMDB9.EB9Nla8jN5J7ZfXITC3okLsLlUQM5o9-uY7ZgTayHwk';

// 1) кэш-вебхуки: отвечают + не устарели. Ответ today-dashboard сохраняем для проверки гейта (§3).
const WH = [
  ['today-dashboard',  '?token=blS1Chm38kO5wab2zPVC', 4],
  ['health-dashboard', '?token=JI45FVfyUJgD7gfkAJJN', 3],
  ['bioage-dashboard', '?token=HbcQb4XNeqMFwMtnOQhx', 27],
  ['weekly-nutrients', '?token=8j1bXp92BF5VabxNq2VN', 30],
  ['recipes', '?token=Bz8nnNaltVyeUKfVLy71', 30],
];
let todayCache = null;
for (const [path, q, maxH] of WH) {
  try {
    const res = await this.helpers.httpRequest({ method: 'GET', url: B + path + q, timeout: 20000, json: true });
    if (path === 'today-dashboard') todayCache = res;
    if (res && res.error) { problems.push(path + ': error=' + res.error); continue; }
    const ua = res && (res.updated_at || res.computed_at);
    if (ua && /^\d{4}-\d{2}-\d{2}T\d/.test(String(ua))) {
      const ageH = (now - new Date(ua).getTime()) / 3600000;
      if (ageH > maxH) problems.push(path + ': кэш устарел на ' + Math.round(ageH) + 'ч (порог ' + maxH + 'ч)');
    } else {
      problems.push(path + ': ответ без метки времени (updated_at/computed_at)');
    }
  } catch (e) { problems.push(path + ': не отвечает (' + String(e.message).slice(0, 60) + ')'); }
}
try {
  const html = await this.helpers.httpRequest({ method: 'GET', url: B + 'dashboard?token=wFSIRB6DO4l6ZrUSlJR5', timeout: 20000 });
  if (!/<!DOCTYPE|<html/i.test(String(html))) problems.push('dashboard (виджет): не отдаёт HTML');
} catch (e) { problems.push('dashboard (виджет): не отвечает (' + String(e.message).slice(0, 60) + ')'); }

// 2) дыры в Daily_Trends и day_sum за 5 дней. Пустой ответ Sheets-ноды = сбой чтения, не отсутствие данных.
function d10(v){ return String(v==null?'':v).trim().slice(0,10); }
function isDate(x){ return /^\d{4}-\d{2}-\d{2}$/.test(x); }
const dtDates = $('Get Daily_Trends').all().map(i => d10(i.json['Дата'] || i.json['Date'])).filter(isDate);
const dsDates = $('Get day_sum').all().map(i => d10(i.json['Date'] || i.json['Дата'])).filter(isDate);
const dtSet = new Set(dtDates), dsSet = new Set(dsDates);
const days5 = [];
for (let k = 2; k <= 6; k++) days5.push(new Date(now + 10*3600000 - k*86400000).toISOString().slice(0, 10));
if (dtSet.size === 0) notes.push('Daily_Trends не прочитан (лимит Google Sheets?) — проверка дыр пропущена');
else { const m = days5.filter(d => !dtSet.has(d)); if (m.length) problems.push('Daily_Trends нет строк за: ' + m.join(', ') + ' (Garmin-пайплайн?)'); }
if (dsSet.size === 0) notes.push('day_sum не прочитан (лимит Google Sheets?) — проверка дыр пропущена');
else { const m = days5.filter(d => !dsSet.has(d)); if (m.length) problems.push('day_sum нет строк за: ' + m.join(', ') + ' (лог еды?)'); }

// 2b) A3 — расширенная проверка дыр + дублей.
const mealDates = $('Get Meals').all().map(i => d10(i.json['Date'] || i.json['Дата'])).filter(isDate);
const mealSet = new Set(mealDates);
if (mealSet.size === 0) notes.push('Meals не прочитан — проверка дыр пропущена');
else { const m = days5.filter(d => !mealSet.has(d)); if (m.length) problems.push('Meals нет записей за: ' + m.join(', ') + ' (лог еды не пишется?)'); }

// Recommendations_Log: еженедельный советник — не должно быть тишины > 8 дней.
const recDates = $('Get Recommendations_Log').all().map(i => d10(i.json['Date'] || i.json['Дата'])).filter(isDate).sort();
if (recDates.length) {
  const ageDays = (new Date(now + 10*3600000 - 0) - new Date(recDates[recDates.length - 1])) / 86400000;
  if (ageDays > 8) problems.push('Recommendations_Log: последняя запись ' + recDates[recDates.length - 1] + ' (' + Math.round(ageDays) + ' дн назад) — советник не отработал?');
}

// Дубли по дате в листах, где 1 строка = 1 день (Daily_Trends, day_sum).
function dupsByDate(rows, key1, key2) {
  const cnt = {};
  rows.map(i => d10(i.json[key1] || i.json[key2])).filter(isDate).forEach(d => cnt[d] = (cnt[d] || 0) + 1);
  return Object.entries(cnt).filter(([, c]) => c > 1).map(([d, c]) => d + '×' + c);
}
const dtDup = dtSet.size ? dupsByDate($('Get Daily_Trends').all(), 'Дата', 'Date') : [];
const dsDup = dsSet.size ? dupsByDate($('Get day_sum').all(), 'Date', 'Дата') : [];
if (dtDup.length) problems.push('🔴 Daily_Trends ДУБЛИ по дате: ' + dtDup.slice(0, 6).join(', '));
if (dsDup.length) problems.push('🔴 day_sum ДУБЛИ по дате: ' + dsDup.slice(0, 6).join(', '));

// 3) safety-гейт — проверяем РЕАЛЬНЫЙ вывод боевого loadGate, а не копию логики.
// Инвариант: у этого пациента активная грыжа L5/S1 в Patient_State → гейт ОБЯЗАН быть blocked.
// Если today-dashboard отдаёт blocked=false — это регрессия loadGate (fail-open).
try {
  const g = todayCache && todayCache.decision && todayCache.decision.gate;
  if (!g) {
    notes.push('гейт: today-dashboard не отдал decision.gate — проверка пропущена');
  } else if (g.blocked !== true) {
    problems.push('🔴 ГЕЙТ НАГРУЗКИ ОТКРЫТ (blocked=' + g.blocked + ', source=' + (g.source || '?')
      + '). При активной грыже L5/S1 это регрессия loadGate — проверь today_build.js / bc.');
  } else if (!/ходьб|плаван/i.test(String(todayCache.decision.verdict || ''))) {
    problems.push('гейт blocked, но verdict «' + todayCache.decision.verdict + '» не про ходьбу/плавание — проверь');
  }
} catch (e) { notes.push('гейт: проверка не удалась (' + String(e.message).slice(0, 50) + ')'); }

// 4) активность воркфлоу — критичные ДОЛЖНЫ быть active. Снятие _Error Handler = тихая смерть оповещения.
const EXPECTED_ACTIVE = [
  '_Error Handler', '_System Check', '_Backup Alert',
  'Health Watchdog', 'Weekly AI Advisor', 'Anamnesis Collector', 'Reports',
  '🚨Capitan', 'Sub-Agent: AI Doctor', 'Sub-Agent: Registrar',
  'today-dashboard (cache)', 'health-dashboard (cache)', 'bioage-dashboard (cache)',
  'Dashboard Cached', 'PhenoAge Calc',
];
try {
  const wf = await this.helpers.httpRequest({ method: 'GET', url: API + 'workflows?limit=250', json: true,
    headers: { 'X-N8N-API-KEY': N8N_KEY }, timeout: 20000 });
  const activeNames = new Set((wf.data || []).filter(w => w.active).map(w => w.name));
  const missing = EXPECTED_ACTIVE.filter(n => !activeNames.has(n));
  if (missing.length) problems.push('🔴 НЕ АКТИВНЫ критичные воркфлоу: ' + missing.join(', '));
} catch (e) {
  notes.push('проверка active-воркфлоу не удалась (' + String(e.message).slice(0, 50) + ') — n8n API?');
}

// 5) статус ночного бэкапа (файл пишет nightly_backup.sh; читаем через рейт-лимит-безопасный путь)
// (само оповещение о бэкапе делает _Backup Alert; здесь — только в утренней сводке для полноты.)

// 6) итог
const ts = new Date(now + 10*3600000).toISOString().slice(0, 16).replace('T', ' ');
let msg;
if (problems.length) {
  msg = '⚠️ <b>Система: проблемы (' + ts + ' ВЛ)</b>\n\n• ' + problems.join('\n• ');
  if (notes.length) msg += '\n\n<i>' + notes.join('; ') + '</i>';
} else if (notes.length) {
  msg = '✅ Система в норме (' + ts + ' ВЛ), но: ' + notes.join('; ') + '.';
} else {
  msg = '✅ Система в норме (' + ts + ' ВЛ). Вебхуки живы, кэши свежие, Daily_Trends/day_sum/Meals без дыр и дублей за 5 дней, советник свежий, гейт blocked (грыжа), критичные воркфлоу active.';
}
return [{ json: { message: msg, has_problems: problems.length > 0, problems, notes } }];

